#[unsafe(no_mangle)]
pub extern "C" fn proj_create_conversion_transverse_mercator(
    ctx: *mut PJ_CONTEXT,
    center_lat: f64,
    center_long: f64,
    scale: f64,
    false_easting: f64,
    false_northing: f64,
    ang_unit_name: *const c_char,
    ang_unit_conv_factor: f64,
    linear_unit_name: *const c_char,
    linear_unit_conv_factor: f64,
) -> *mut PJ {
    guard(std::ptr::null_mut(), || {
        let units = Units::new(
            ang_unit_name,
            ang_unit_conv_factor,
            linear_unit_name,
            linear_unit_conv_factor,
        );
        finish(
            ctx,
            Conversion::create_transverse_mercator(
                &OpProps::new(),
                units.angle(center_lat),
                units.angle(center_long),
                units.scale(scale),
                units.length(false_easting),
                units.length(false_northing),
            ),
            "proj_create_conversion_transverse_mercator",
        )
    })
}

